INSERT INTO `parametro` (`parametro_id`, `para_grupo`, `para_nombre`, `para_codigo`, `para_tipo`, `para_valor`, `para_opcion`, `para_help`, `para_estado`, `para_orden`) VALUES
(13,	'Sitio',	'Bases Legales',	'BASESLEGALES',	'archivo',	'bases-legales-escudo-20220920144623.pdf',	'',	'Extensión PDF',	'A',	10);
INSERT INTO `pregunta` (`pregunta_id`, `preg_pregunta`, `preg_respuesta`, `preg_estado`, `preg_orden`) VALUES
(1,	'¿CUÁNDO PARTE Y CUÁNDO TERMINA LA PROMOCIÓN?',	'El Concurso estará vigente desde el día 18 de agosto de 2025, hasta el día 26 de octubre de 2025, ambas fechas inclusive.\r\n',	'A',	10),
(2,	'¿TENGO QUE SER MAYOR DE EDAD?',	'Sí, para poder participar de este concurso debes ser mayor de 18 años.',	'A',	20),
(3,	'¿QUÉ PUEDO GANAR?',	'Uno de los 1.010 premios, que serán entregados a 260 ganadores en total.\r\n\r\n<strong>Cineplanet</strong>: 40 ganadores; 4 por semana cada uno con 4 entradas.\r\n<strong>Happyland</strong>: 30 ganadores; 3 por semana cada uno con 4 tarjetas de juego de $25.000. \r\n<strong>Mampato</strong>: 60 ganadores; 6 por semana cada uno con 4 entradas.\r\n<strong>Fantasilandia</strong>: 40 ganadores; 4 por semana cada uno con 4 entradas. \r\n<strong>Chuck E Chesse</strong>: 30 ganadores; 3 por semana cada uno con 4 tarjetas de 30 minutos o puntos.\r\n<strong>Family Park</strong>: 30 ganadores; 3 por semana cada uno con 4 tarjetas de juego de $12.000 + $12.000 bonus.\r\n<strong>KidZania</strong>: 30 ganadores; 3 por semana cada uno con 3 entradas.',	'A',	40),
(4,	'¿CÓMO SE HARÁ LA ENTREGA DE LOS PREMIOS?',	'Las personas que resulten ganadoras, recibirán un llamado telefónico de parte de una ejecutiva de la agencia Virus Publicidad Ltda. La cual confirmará el correo ingresado en la web y procederá a enviar los premios de manera digital al mismo correo.',	'A',	50),
(5,	'¿CÓMO SE HARÁ LA ENTREGA DE LOS PREMIOS? ',	'La entrega del premio, $100.000.- (cien mil pesos) en efectivo, se realizará de lunes a viernes previo contacto con los ganadores para obtener sus datos bancarios. Será a través de transferencia electrónica en dichas cuentas.',	'I',	70),
(6,	'¿PUEDO CANEJAR EL PREMIO POR DINERO?',	'Los premios son nominativos y no podrán canjearse por dinero u otros objetos. El ganador no tendrá derecho a reclamar cambio, reemplazo, dinero o prestación alguna de ECCU si no hiciera efectivo el premio en el plazo indicado en las bases legales. ',	'A',	60),
(7,	'¿CÓMO PUEDO PARTICIPAR?',	'Sigue los siguientes pasos y podrás participar:\r\n\r\n1.	Comprar alguno de los siguientes productos Bilz Zero o Pap Zero en sus formatos PET 600ml, 1,5L, 2L y 3L con etiqueta promocional.\r\n2.	Escanear el código QR ubicado en la etiqueta del producto o ingresar al sitio web.\r\n3.	Dentro del Sitio Web, deberás pinchar el botón de “Participa”.\r\n4.	Completar el formulario con sus datos personales. \r\n5.	Subir una fotografía con el producto adherido adquirido (solo se puede subir la misma foto 1 vez)\r\n6.	Luego, debes la actividad por la cual quisieras participar: Cineplanet, Happyland, Mampato, Fantasilandia, Chuck e Chesse, KidZania o Family Park. \r\n7.	Para finalizar, deberás aceptar los Términos y Condiciones y Bases Legales.',	'A',	30),
(8,	'¿CÓMO SÉ SI ME ESTÁN CONTACTANDO DE BILZ Y PAP Y NO ES UNA MENTIRA?',	'Los concursantes solo serán contactados vía telefónica por uno de nuestros ejecutivos de Virus Publicidad. Tú solo deberás confirmar los datos ingresados en el formulario de participación que te indicaremos. Nunca se te pedirán datos personales fuera de los ingresados en el formulario.\r\n',	'A',	80),
(9,	'¿DÓNDE PUEDO OBTENER MÁS INFORMACIÓN?',	'En el sitio web diversion.bilzypap.cl podrás encontrar toda la información sobre la promoción: bases legales, premios, cómo participar, formulario para ingresar datos y participar. Sugerimos leer las bases legales de la promoción. Si aun así tienes dudas, puedes contactarnos enviando mail a cbusch@viruspublicidad.cl (Virus Publicidad Ltda.)',	'A',	90),
(10,	'¿CÓMO SÉ SI ME ESTÁN CONTACTANDO DE LA PROMO ZERO Y NO ES UNA MENTIRA? ',	'Los concursantes solo serán contactados a través de mail y/o vía telefónica por uno de nuestros ejecutivos de Virus Publicidad. Tú solo deberás confirmar los datos ingresados en el formulario de participación y enviarnos una foto de la etiqueta con la que participaste (legible), todo esto dentro de un plazo máximo de 5 días hábiles desde la fecha del respectivo sorteo, caducará el derecho del exigir el premio.',	'I',	100),
(11,	'¿DÓNDE PUEDO OBTENER MÁS INFORMACIÓN? ',	'En el sitio web lapromozero.cl podrás encontrar toda la información sobre la promoción: bases legales, premios, cómo participar, formulario para ingresar datos y participar. Sugerimos leer las bases legales de la promoción. Si aun así tienes dudas, puedes contactarnos enviando mail a concursos@viruspublicidad.cl (Virus Publicidad Ltda.).',	'I',	110);
